# Initially generated by GitHub Copilot.

from __future__ import annotations

import unittest
from pathlib import Path
from tempfile import TemporaryDirectory
from unittest.mock import patch

from accgram import run_orig


class TestAccgramRunOrig(unittest.TestCase):
    def test_normalize_strips_bb_prefix_and_adds_book_heading(self):
        raw = "ob1:1 X:AZO73WN\nob1:2 HIN."\
            "71H\n"
        normalized = run_orig._normalize_for_accents(raw_text=raw, bb="ob")
        self.assertTrue(normalized.startswith("Obadiah\n"))
        self.assertIn("1:1 X:AZO73WN\n", normalized)
        self.assertIn("1:2 HIN.71H\n", normalized)
        self.assertNotIn("ob1:1", normalized)

    def test_run_orig_writes_stdout_and_stderr_sidecars(self):
        with TemporaryDirectory() as tmp_dir:
            base = Path(tmp_dir)
            in_dir = base / "in"
            out_dir = base / "out"
            stderr_dir = base / "err"
            accents_bin = base / "accents"

            in_dir.mkdir(parents=True, exist_ok=True)
            accents_bin.write_text("fake-binary", encoding="utf-8")

            (in_dir / "wlc_422_ps_ob.txt").write_text("ob1:1 X\n", encoding="utf-8")
            (in_dir / "wlc_422_ps_gn.txt").write_text("gn1:1 Y\n", encoding="utf-8")

            calls: list[list[str]] = []

            def fake_run(cmd, input, capture_output, check):
                self.assertEqual(cmd[0], "wsl")
                self.assertEqual(cmd[2], "-p")
                self.assertTrue(capture_output)
                self.assertFalse(check)
                calls.append(cmd)

                class FakeCompletedProcess:
                    def __init__(self, stdout: bytes, stderr: bytes, returncode: int = 0):
                        self.stdout = stdout
                        self.stderr = stderr
                        self.returncode = returncode

                payload = input.decode("utf-8")
                if "Obadiah" in payload:
                    return FakeCompletedProcess(stdout=b"TREE\n", stderr=b"")
                return FakeCompletedProcess(stdout=b"", stderr=b"accents warning\n")

            with patch("accgram.run_orig.subprocess.run", side_effect=fake_run):
                result = run_orig.run_orig(
                    in_dir=in_dir,
                    out_dir=out_dir,
                    stderr_dir=stderr_dir,
                    accents_bin=accents_bin,
                    normalize=True,
                )

            self.assertEqual(result.input_count, 2)
            self.assertEqual(result.output_count, 2)
            self.assertEqual(result.nonempty_output_count, 1)
            self.assertEqual(result.stderr_nonempty_count, 1)
            self.assertEqual(result.nonzero_exit_count, 0)
            self.assertEqual(len(calls), 2)

            self.assertEqual((out_dir / "wlc_422_ps_ob_ag.txt").read_text(encoding="utf-8"), "TREE\n")
            self.assertEqual(
                (stderr_dir / "wlc_422_ps_gn_ag.stderr.txt").read_text(encoding="utf-8"),
                "accents warning\n",
            )

    def test_run_orig_reports_nonzero_exit_with_empty_stderr(self):
        with TemporaryDirectory() as tmp_dir:
            base = Path(tmp_dir)
            in_dir = base / "in"
            out_dir = base / "out"
            stderr_dir = base / "err"
            accents_bin = base / "accents"

            in_dir.mkdir(parents=True, exist_ok=True)
            accents_bin.write_text("fake-binary", encoding="utf-8")
            (in_dir / "wlc_422_ps_ob.txt").write_text("ob1:1 X\n", encoding="utf-8")

            class FakeCompletedProcess:
                def __init__(self):
                    self.stdout = b""
                    self.stderr = b""
                    self.returncode = 7

            with patch("accgram.run_orig.subprocess.run", return_value=FakeCompletedProcess()):
                result = run_orig.run_orig(
                    in_dir=in_dir,
                    out_dir=out_dir,
                    stderr_dir=stderr_dir,
                    accents_bin=accents_bin,
                    normalize=True,
                )

            self.assertEqual(result.nonzero_exit_count, 1)
            sidecar = (stderr_dir / "wlc_422_ps_ob_ag.stderr.txt").read_text(encoding="utf-8")
            self.assertIn("accents exited with code 7", sidecar)


if __name__ == "__main__":
    unittest.main()